/**
 * Every icon the app uses comes through this file, so changing the icon library
 * later means editing one place. The set is Solar (CC BY 4.0, 480 Design); the
 * paths are generated by `npm run icons` from scripts/generate-icons.mjs.
 */
import type { SVGProps } from 'react'
import { SOLAR_BODIES } from './solar-icons'

type IconProps = Omit<SVGProps<SVGSVGElement>, 'children'> & { size?: number }

function make(body: string) {
  return function Icon({ size = 16, ...props }: IconProps) {
    return (
      <svg
        viewBox="0 0 24 24"
        width={size}
        height={size}
        aria-hidden="true"
        {...props}
        dangerouslySetInnerHTML={{ __html: body }}
      />
    )
  }
}

